CREATE PROCEDURE dbo.sp_alterdiagram
(
	@diagramname 	sysname,
	@owner_id	int	= null,
	@version 	int,
	@definition 	varbinary(max)
)
WITH EXECUTE AS 'dbo'
AS
BEGIN
	set nocount on

	declare @theId 			int
	declare @retval 		int
	declare @IsDbo 			int

	declare @UIDFound 		int
	declare @DiagId			int
	declare @ShouldChangeUID	int

	if(@diagramname is null)
	begin
		RAISERROR ('Invalid ARG', 16, 1)
		return -1
	end

	execute as caller;
	select @theId = DATABASE_PRINCIPAL_ID();	 
	select @IsDbo = IS_MEMBER(N'db_owner'); 
	if(@owner_id is null)
		select @owner_id = @theId;
	revert;

	select @ShouldChangeUID = 0
	select @DiagId = diagram_id, @UIDFound = principal_id from dbo.sysdiagrams where principal_id = @owner_id and name = @diagramname 

	if(@DiagId IS NULL or (@IsDbo = 0 and @theId <> @UIDFound))
	begin
		RAISERROR ('Diagram does not exist or you do not have permission.', 16, 1);
		return -3
	end

	if(@IsDbo <> 0)
	begin
		if(@UIDFound is null or USER_NAME(@UIDFound) is null) -- invalid principal_id
		begin
			select @ShouldChangeUID = 1 ;
		end
	end

	-- update dds data			
	update dbo.sysdiagrams set definition = @definition where diagram_id = @DiagId ;

	-- change owner
	if(@ShouldChangeUID = 1)
		update dbo.sysdiagrams set principal_id = @theId where diagram_id = @DiagId ;

	-- update dds version
	if(@version is not null)
		update dbo.sysdiagrams set version = @version where diagram_id = @DiagId ;

	return 0
END

CREATE   PROCEDURE dbo.sp_batch_insert_order_request
    @CreateOrderRequestList dbo.orderRequestTableType READONLY
AS
BEGIN
    SET NOCOUNT ON;

    -- Time variables
    DECLARE @StartTime DATETIME2 = SYSUTCDATETIME();
    DECLARE @EndTime DATETIME2;
    DECLARE @DurationInMilliseconds BIGINT;

    -- Temporary table to store only id and order_id
    DECLARE @InsertedDetails TABLE (
        id BIGINT,
        order_no VARCHAR(100)
    );

    -- Insert into the target table and capture id and order_id
    INSERT INTO dbo.order_request (
       txn_ref_no, status, account_id, ref_id, created_by, created_date,
       last_modified_by, last_modified_date, channel_type, order_no, metadata
    )
    OUTPUT inserted.id, inserted.order_no
    INTO @InsertedDetails
    SELECT 
        txn_ref_no, status, account_id, ref_id, created_by, created_date,
       last_modified_by, last_modified_date, channel_type, order_no, metadata
    FROM @CreateOrderRequestList;

    -- End time and duration
    SET @EndTime = SYSUTCDATETIME();
    SET @DurationInMilliseconds = DATEDIFF(MILLISECOND, @StartTime, @EndTime);

    -- Return id and order_no of all inserted rows
    SELECT id, order_no FROM @InsertedDetails;

    -- Return duration as a separate result set
    SELECT @DurationInMilliseconds AS DurationInMilliseconds;
END;

CREATE PROCEDURE dbo.sp_creatediagram
(
	@diagramname 	sysname,
	@owner_id		int	= null, 	
	@version 		int,
	@definition 	varbinary(max)
)
WITH EXECUTE AS 'dbo'
AS
BEGIN
	set nocount on

	declare @theId int
	declare @retval int
	declare @IsDbo	int
	declare @userName sysname
	if(@version is null or @diagramname is null)
	begin
		RAISERROR (N'E_INVALIDARG', 16, 1);
		return -1
	end

	execute as caller;
	select @theId = DATABASE_PRINCIPAL_ID(); 
	select @IsDbo = IS_MEMBER(N'db_owner');
	revert; 

	if @owner_id is null
	begin
		select @owner_id = @theId;
	end
	else
	begin
		if @theId <> @owner_id
		begin
			if @IsDbo = 0
			begin
				RAISERROR (N'E_INVALIDARG', 16, 1);
				return -1
			end
			select @theId = @owner_id
		end
	end
	-- next 2 line only for test, will be removed after define name unique
	if EXISTS(select diagram_id from dbo.sysdiagrams where principal_id = @theId and name = @diagramname)
	begin
		RAISERROR ('The name is already used.', 16, 1);
		return -2
	end

	insert into dbo.sysdiagrams(name, principal_id , version, definition)
			VALUES(@diagramname, @theId, @version, @definition) ;

	select @retval = @@IDENTITY 
	return @retval
END

create    PROCEDURE [dbo].[sp_dds_interest_on_closing_bal] -- sp_dds_interest_on_closing_bal 520816,'2020-11-09'
@accountId bigint,
@currentDate datetime
AS
BEGIN
DECLARE @accountOpenDate DATE = (SELECT CAST(account_open_date AS DATE) FROM BSGCORE..account_master WHERE account_id = @accountId AND is_active = 1);
    PRINT 'The @accountOpenDate is = ' + CONVERT(VARCHAR,@accountOpenDate);
DECLARE @age INT = (case WHEN (datediff(month, @accountOpenDate, @currentDate) = 6) then dbo.FullMonthsSeparation(@accountOpenDate, @currentDate)
                     WHEN (datediff(month, @accountOpenDate, @currentDate) = 12) then dbo.FullMonthsSeparation(@accountOpenDate, @currentDate)
                     WHEN (datediff(month, @accountOpenDate, @currentDate) > 12) then 12
                     else datediff(month, @accountOpenDate, @currentDate)
                     END);
    PRINT 'The @age is = ' + CONVERT(VARCHAR,@age);
DECLARE @intAge INT = @age - 1;
    PRINT 'The @intAge is = ' + CONVERT(VARCHAR,@intAge);
DECLARE @balSum DECIMAL(18,2) = 0.00;
DECLARE @counter INT = 1;
DECLARE @intDate DATE = @accountOpenDate;
WHILE ( @counter <= @intAge)
BEGIN
    SET @intDate = DATEADD(day, 1, eomonth(@intDate));
    PRINT 'The month is = ' + CONVERT(VARCHAR,@intDate);
    SET @balSum = @balSum + (SELECT ISNULL((SELECT available_balance FROM BSGACCOUNTING..account_balance WHERE account_id = @accountId and txn_date = 
        (SELECT max(txn_date) FROM BSGACCOUNTING..account_balance WHERE account_id = @accountId and txn_date < @intDate)),0));
    PRINT 'The @balSum is = ' + CAST(@balSum AS VARCHAR);
    SET @counter  = @counter  + 1;
END
DECLARE @effectiveDate DATE = (SELECT max(effective_date) FROM BSGCORE..dds_closure_rates WHERE effective_date <= @accountOpenDate AND from_months <= @age AND to_months > @age AND is_active = 1);
DECLARE @roi DECIMAL(18,2) = (SELECT roi FROM BSGCORE..dds_closure_rates WHERE effective_date = @effectiveDate AND from_months <= @age AND to_months > @age AND is_active = 1);
    PRINT 'The @effectiveDate is = ' + CONVERT(VARCHAR,@effectiveDate);
DECLARE @interest DECIMAL(18,2) = ((@balSum * @roi)/1200);
SELECT ISNULL(@interest,0) AS intAmt;
END;

CREATE PROCEDURE dbo.sp_dropdiagram
(
	@diagramname 	sysname,
	@owner_id	int	= null
)
WITH EXECUTE AS 'dbo'
AS
BEGIN
	set nocount on
	declare @theId 			int
	declare @IsDbo 			int

	declare @UIDFound 		int
	declare @DiagId			int

	if(@diagramname is null)
	begin
		RAISERROR ('Invalid value', 16, 1);
		return -1
	end

	EXECUTE AS CALLER;
	select @theId = DATABASE_PRINCIPAL_ID();
	select @IsDbo = IS_MEMBER(N'db_owner'); 
	if(@owner_id is null)
		select @owner_id = @theId;
	REVERT; 

	select @DiagId = diagram_id, @UIDFound = principal_id from dbo.sysdiagrams where principal_id = @owner_id and name = @diagramname 
	if(@DiagId IS NULL or (@IsDbo = 0 and @UIDFound <> @theId))
	begin
		RAISERROR ('Diagram does not exist or you do not have permission.', 16, 1)
		return -3
	end

	delete from dbo.sysdiagrams where diagram_id = @DiagId;

	return 0;
END

